    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Long straight colored object is the color to use.
    colors = [c for c in counts if c != bg]
    def run(c):
        best = 0
        for row in grid:
            n = 0
            for v in row:
                n = n + 1 if v == c else 0
                best = max(best, n)
        for j in range(w):
            n = 0
            for i in range(h):
                n = n + 1 if grid[i][j] == c else 0
                best = max(best, n)
        return best
    paint = max(colors, key=run)
    paint_cells = [(r, c) for r in range(h) for c in range(w)
                   if grid[r][c] == paint]

    # Find the nearest other object, using distance between object boundaries.
    seen = set()
    best = None
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col in (bg, paint) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                a, b = stack.pop()
                cells.append((a, b))
                for x, y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0 <= x < h and 0 <= y < w and (x,y) not in seen and grid[x][y] == col:
                        seen.add((x,y))
                        stack.append((x,y))
            d = min((a-x)**2 + (b-y)**2 for a,b in cells for x,y in paint_cells)
            if best is None or d < best[0]:
                best = (d, cells)

    out = [row[:] for row in grid]
    if best:
        for r, c in best[1]:
            out[r][c] = paint
    return out
